export const getGetChatHistoryUrl = (params?: GetChatHistoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/chat/messages?${stringifiedParams}` : `/api/chat/messages`
}

/**
 * @summary Get chat history
 */
export const getChatHistory = async (params?: GetChatHistoryParams, options?: Parameters<typeof customFetch>[1]): Promise<ChatHistory> => {

  return customFetch<ChatHistory>(getGetChatHistoryUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





